export const LT_ARTILLERY_PROFILES = Object.freeze(Object.fromEntries(rows.map(p=>[p.modeId,Object.freeze(p)])));
export const ltArtilleryProfile=value=>LT_ARTILLERY_PROFILES[typeof value==='string'?value:value?.standaloneModeId??value?.catalogModeId]??null;
export const ltArtilleryAmmo=(p,id)=>p?.ammunition.find(a=>a.id===id)??null;
/** Source fit and the missing delivery mechanics are separate verdicts. No GM approval. */
export function ltArtilleryFutureLoad(modeId,id){
 const p=ltArtilleryProfile(modeId),mass={incendiary_sphere:10,paper_bomb:5,iron_bomb:30}[id];if(!p||!mass)return null;
 const factor=mass/p.projectileMass,correctEngine=p.oneArmed&&(id!=='incendiary_sphere'||p.name.startsWith('Beam Sling'));
 const fitted=correctEngine&&Object.hasOwn(LT_OVERWEIGHT_RANGE,String(factor));
 return {id,source:'LT83–85',mass,factor,sourceFit:fitted?'confirmed':'undetermined',status:fitted?'BLOCKED':'SOURCE_UNDETERMINED',
  rangeFactor:fitted?LT_OVERWEIGHT_RANGE[String(factor)]:null,
  reason:fitted?(id==='incendiary_sphere'?'Подтверждена доставка Beam Sling; нужны отдельные зажигание, падение и ручное/зональное применение горящей сферы.':'Масса допускается таблицей LT83; нужны отдельные доставка, падение, взведение и детонация бомбы. Эти механики отложены.'):
   'LT83–85 не определяет подходящий пусковой профиль этого устройства для данной машины и массы. Профиль обычного камня ему не присваивается.'};
}
export function ltArtilleryConfiguration(weapon){
 const s=weapon?.ltEarly?.settings??{};
 return {crew:Number.isSafeInteger(s.crew)&&s.crew>0?s.crew:1,ignitionReady:s.ignitionReady===true,setupReady:s.setupReady===true,
  mountReady:s.mountReady===true,visionReady:s.visionReady===true,standAside:s.standAside===true,procedureReady:s.procedureReady===true,
  cocking:s.cocking==='hand'?'hand':'crank',applyArmST:s.applyArmST===true,indirect:s.indirect===true};
}
export function ltArtilleryAdmission(modeId,ammoId,kind){
 const p=ltArtilleryProfile(modeId);if(!p)return null;
 const metal=['lt_bombard_metal_ball_lt87','lt_bombard_large_metal_ball_lt87'].includes(ammoId);
 const allowed=kind==='ammo-item'&&!!ltArtilleryAmmo(p,ammoId);
 return {status:metal?'undetermined':allowed?'compatible':'incompatible',reasons:allowed?[]:[{code:metal?'LT_BOMBARD_METAL_UNPROVEN':p.bundle&&/^lt_ballista_\d+_lb_stone_lt81$/.test(ammoId)?'LT_BUNDLE_REQUIRES_SEPARATE_STONES':'LT_ARTILLERY_WRONG_PROJECTILE',
  message:metal?'LT87–88 не подтверждает металлическое ядро для этого Bombard.':'Снаряд или размер не подтверждён для этого режима LT.'}]};
}
export function projectLTArtillerySource(book,data){
 if(book==='lt'){
  const grape=data.projectile_options.find(p=>p.id==='grapeshot');if(grape)Object.assign(grape,{pellets_formula:'floor(40 * full_round_weight_lb)',count_source:'LT88; B9',
   notes_ru:'Число шариков 0,5″: 40 × масса ПОЛНОГО заряда (включая порох), вниз по B9. Один холщовый мешок; Damage /√N, RoF ×N, Range60/600, Rcl1. LT88.'});
  const overweight=data.projectile_options.find(p=>p.id==='catapult_overweight');if(overweight)overweight.status='OWNER_FITTED_PHYSICAL_RECIPE';
  const pot=data.projectile_options.find(p=>p.id==='incendiary_catapult_pot');if(pot)pot.status='SOURCE_FIT_AND_DELIVERY_UNDETERMINED';
  for(const id of ['incendiary_sphere','paper_bomb','iron_bomb']){const r=data.projectile_options.find(p=>p.id===id);if(r){r.status='INDIVIDUAL_SOURCE_FIT_AND_DELIVERY_FUTURE';if(id==='iron_bomb')r.notes_ru='Железная бомба: отдельные взведение, доставка и детонация; не обычный камень. LT85.';}}
 }
 if(book==='weapons')for(const e of data.equipment??[])if(e.source==='LT')for(const m of e.modes??[]){
  const p=ltArtilleryProfile(m.weapon_mode_id);if(!p||e.equipment_id!==p.equipmentId)continue;
  const stats={...p.stats};delete stats.damage;Object.assign(m.stats,stats);
  const match=/^(\d+d(?:[+-]\d+)?(?:x\d+)?)\s*(?:\(([^)]+)\))?\s+(\S+)$/.exec(p.stats.damage);
  if(match)m.stats.damage={base:match[1],...(match[2]?{armor_divisor:match[2]}:{}),type:match[3]};
  m.raw_calc={...m.raw_calc,damage:p.stats.damage};m.governing_skill=structuredClone(p.governing_skill);m.defaults=structuredClone(p.defaults);
  m.lt_artillery_contract=structuredClone(p);m.lt_ammo_item_ids=[...new Set([...(m.lt_ammo_item_ids??[]),...p.ammoIds])];
  if(!p.mechanical)m.weapon_family='firearm';
  if(p.personal)m.lt_ranged_contract={...m.lt_ranged_contract,rclNotApplicable:true,source:p.source};
 }
 if(book==='lt')for(const p of rows)for(const a of p.ammunition){
  let r=data.ammo_items.find(x=>x.id===a.id);
  if(!r){r={id:a.id,name:a.name,ammo_family_id:a.id,variant_id:null,specific_model_only:true,catalog_added_from_book:true,
   source_equipment_id:p.equipmentId,weapon_mode_ids:[],projectile_classes:[p.mechanical?p.bolt?'artillery_bolt':'artillery_spherical':'black_powder_cannonball'],source_ref_raw:a.source??p.source,tech_level_raw:String(a.tl??p.tl)};data.ammo_items.push(r);}
  r.weapon_mode_ids=[...new Set([...(r.weapon_mode_ids??[]),p.modeId])];r.lt_artillery_physical=true;
  if(p.mechanical&&Number.isFinite(a.mass)&&['lead','stone','bolt','bundle-lead','bundle-stone'].includes(a.kind)){
   const rate={lead:1.6,stone:1,bolt:33,'bundle-lead':1.6,'bundle-stone':1}[a.kind];r.weight_lb=a.mass;r.price_per_lb_usd=rate;r.price_usd=Number((a.mass*rate).toPrecision(12));
   r.price_formula=String(rate)+' USD × projectile weight (lb.)';r.source_ref_price='LT81';
  }
  let f=data.ammo_families.find(x=>x.id===r.ammo_family_id);if(!f){f={id:r.ammo_family_id,name:r.name,ammo_item_ids:[],compatible_weapon_mode_ids:[]};data.ammo_families.push(f);}
  f.ammo_item_ids=[...new Set([...(f.ammo_item_ids??[]),r.id])];f.compatible_weapon_mode_ids=[...new Set([...(f.compatible_weapon_mode_ids??[]),p.modeId])];
 }
 return data;
}
